"use client";

import { Switch as SwitchPrimitive } from "@base-ui/react/switch";

import { cn } from "@/lib/utils";
import { controlChecked } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Playful console Switch: a 2.5rem by 1.5rem cream track with an olive edge
 * and a white knob. On, the track becomes the orange key of the primary
 * button and the knob slides across.
 */
function Switch({ className, ...props }: WithClassName<SwitchPrimitive.Root.Props>) {
  return (
    <SwitchPrimitive.Root
      data-slot="switch"
      className={cn(
        "group/switch peer inline-flex h-6 w-10 shrink-0 cursor-pointer items-center rounded-full border-[0.09375rem] border-(--line-strong) bg-(--surface-3) p-px",
        "transition-[background-color,border-color,box-shadow] duration-fast ease-out",
        "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
        "data-[disabled]:cursor-not-allowed data-[disabled]:bg-secondary",
        controlChecked,
        className,
      )}
      {...props}
    >
      <SwitchPrimitive.Thumb
        data-slot="switch-thumb"
        className={cn(
          "pointer-events-none block size-4.5 rounded-full border-[0.09375rem] border-(--line-strong) bg-(--thumb) shadow-(--shadow-thumb)",
          "data-[checked]:translate-x-4 data-[checked]:border-(--primary-rim) data-[unchecked]:translate-x-0",
          "data-[disabled]:bg-muted data-[disabled]:shadow-none",
          "origin-left data-[checked]:origin-right rtl:origin-right rtl:data-[checked]:origin-left transition-[translate,scale,transform-origin,background-color,box-shadow] duration-[260ms,140ms,0ms,150ms,150ms] delay-[0ms,0ms,140ms,0ms,0ms] ease-out motion-safe:group-active/switch:scale-x-[1.18] motion-reduce:transition-none",
        )}
      />
    </SwitchPrimitive.Root>
  );
}
Switch.displayName = "Switch";

export { Switch };
